/* From Uiverse.io by wizard503  - Tags: social, button, share */
.__UIV_SCOPE__ .share {
  width: 150px;
  height: 150px;
  margin: 5em auto;
  background: rgba(10, 237, 189, 1);
  background: -webkit-radial-gradient(
    top left,
    rgba(10, 237, 189, 1),
    rgba(37, 211, 103, 1)
  );
  background: -moz-radial-gradient(
    top left,
    rgba(10, 237, 189, 1),
    rgba(37, 211, 103, 1)
  );
  background: radial-gradient(
    to bottom right,
    rgba(10, 237, 189, 1),
    rgba(37, 211, 103, 1)
  );
  text-align: center;
  border-radius: 100%;
  overflow: hidden;
  position: relative;
  box-shadow: 0 20px 20px rgba(0, 0, 0, 0.2);
}

.__UIV_SCOPE__ .share a {
  display: -webkit-inline-box;
  display: -ms-inline-flexbox;
  display: inline-flex;
  width: 90px;
  height: 90px;
  position: relative;
  z-index: 1;
}

.__UIV_SCOPE__ .share::after {
  content: "Share";
  position: absolute;
  left: 0;
  right: 0;
  top: 40%;
  font-size: 25px;
  font-weight: bold;
  font-style: italic;
  text-transform: uppercase;
  color: #fff;
}

.__UIV_SCOPE__ .share:hover::after {
  color: transparent;
}

.__UIV_SCOPE__ .share:hover {
  background: rgba(242, 41, 92, 1);
  background: -webkit-radial-gradient(
    top left,
    rgba(242, 41, 92, 1),
    rgba(41, 172, 225, 1)
  );
  background: -moz-radial-gradient(
    top left,
    rgba(242, 41, 92, 1),
    rgba(41, 172, 225, 1)
  );
  background: radial-gradient(
    to bottom right,
    rgba(242, 41, 92, 1),
    rgba(41, 172, 225, 1)
  );
}

.__UIV_SCOPE__ .share a.fb {
  background: #1266f1;
  top: -5.65em;
  left: -2.83em;
  -webkit-transition: all 0.3s ease-in-out;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .share a.tw {
  background: #28abe1;
  top: -6.55em;
  right: -9.39em;
  -webkit-transition: all 0.3s ease-in-out;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .share a.ins {
  background: #f2295b;
  bottom: 6.7em;
  left: -7.5em;
  -webkit-tra3nsition: all 0.3s ease-in-out;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .share a.wh {
  background: #25d366;
  right: -2.81em;
  bottom: 7.5em;
  -webkit-transition: all 0.3s ease-in-out;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .share:hover a.fb {
  top: -0.96em;
}

.__UIV_SCOPE__ .share:hover a.tw {
  right: -2.8em;
}

.__UIV_SCOPE__ .share:hover a.ins {
  left: -2.84em;
}

.__UIV_SCOPE__ .share:hover a.wh {
  bottom: 12.3em;
}

.__UIV_SCOPE__ .facebook {
  padding-top: 45%;
}

.__UIV_SCOPE__ .instagram {
  padding-left: 30%;
  padding-top: 15%;
}

.__UIV_SCOPE__ .whatsapp {
  padding-left: 15%;
  padding-top: 15%;
}

.__UIV_SCOPE__ .twitter {
  padding-top: 25%;
  padding-left: 10%;
}

.__UIV_SCOPE__ .fb:hover {
  box-shadow: 0px 10px 40px rgba(0, 0, 0, 0.5) inset;
}

.__UIV_SCOPE__ .tw:hover {
  box-shadow: 10px 5px 30px 2px rgba(0, 0, 0, 0.5) inset;
}

.__UIV_SCOPE__ .ins:hover {
  box-shadow: 0px 10px 25px rgba(0, 0, 0, 0.5) inset;
}

.__UIV_SCOPE__ .wh:hover {
  box-shadow: 10px 20px 20px rgba(0, 0, 0, 0.5) inset;
}
